54	    private static void validateVerticesCount(int vertices) {
55	        if (vertices <= 0) {
56	            throw new IllegalArgumentException("vertices must be positive");
57	        }
58	    }
59	
60	    private static void validateEdgeData(int[][] edgeData) {
61	        if (edgeData == null) {
62	            throw new IllegalArgumentException("edges must not be null");
63	        }
64	    }
65	
66	    private static void validateVertex(int vertex, int vertices, String label) {
